// Signs release builds with your own key when it's set up, and with the
// debug key otherwise, so anyone can still build from a fresh clone.
//
// `android/` is regenerated by `expo prebuild`, so the signing setup is added
// here rather than edited by hand. The key's location and passwords never
// enter the repository: put them in ~/.gradle/gradle.properties:
//
//   TOMOS_RELEASE_STORE_FILE=/home/you/keys/tomos-release.jks
//   TOMOS_RELEASE_STORE_PASSWORD=...
//   TOMOS_RELEASE_KEY_ALIAS=tomos
//   TOMOS_RELEASE_KEY_PASSWORD=...
const { withAppBuildGradle } = require('@expo/config-plugins');

const PROPS = {
  storeFile: 'TOMOS_RELEASE_STORE_FILE',
  storePassword: 'TOMOS_RELEASE_STORE_PASSWORD',
  keyAlias: 'TOMOS_RELEASE_KEY_ALIAS',
  keyPassword: 'TOMOS_RELEASE_KEY_PASSWORD',
};

const RELEASE_CONFIG = `        release {
            if (findProperty('${PROPS.storeFile}')) {
                storeFile file(findProperty('${PROPS.storeFile}'))
                storePassword findProperty('${PROPS.storePassword}')
                keyAlias findProperty('${PROPS.keyAlias}')
                keyPassword findProperty('${PROPS.keyPassword}')
            }
        }
`;

const RELEASE_SIGNING = `signingConfig findProperty('${PROPS.storeFile}') ? signingConfigs.release : signingConfigs.debug`;

/** app/build.gradle with release signing added. Safe to apply more than once. */
function addReleaseSigning(gradle) {
  if (gradle.includes(RELEASE_SIGNING)) return gradle;
  const fail = (what) => {
    throw new Error(`withReleaseSigning: can't add release signing, ${what} not found in app/build.gradle`);
  };

  const configsAt = gradle.indexOf('signingConfigs {');
  if (configsAt < 0) fail('signingConfigs');
  const afterConfigs = configsAt + 'signingConfigs {\n'.length;
  let out = gradle.slice(0, afterConfigs) + RELEASE_CONFIG + gradle.slice(afterConfigs);

  const typesAt = out.indexOf('buildTypes {');
  const releaseAt = typesAt < 0 ? -1 : out.indexOf('release {', typesAt);
  if (releaseAt < 0) fail('the release build type');
  const debugSigning = 'signingConfig signingConfigs.debug';
  const signingAt = out.indexOf(debugSigning, releaseAt);
  const releaseEnd = out.indexOf('\n        }', releaseAt);
  if (signingAt < 0 || signingAt > releaseEnd) fail("the release build type's signingConfig");
  out = out.slice(0, signingAt) + RELEASE_SIGNING + out.slice(signingAt + debugSigning.length);
  return out;
}

const withReleaseSigning = (config) =>
  withAppBuildGradle(config, (c) => {
    c.modResults.contents = addReleaseSigning(c.modResults.contents);
    return c;
  });

module.exports = withReleaseSigning;
module.exports.addReleaseSigning = addReleaseSigning;
module.exports.PROPS = PROPS;
